INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'choice', 3, '{"stem": "选择(3)：如图，甲的周长+乙的周长（  ）长方形的周长。A.小于  B.等于  C.大于"}', 'C', '甲周长=长+宽+曲线; 乙周长=长+宽+曲线; 甲+乙=2长+2宽+2曲线=长方形周长+2曲线>长方形周长', 'jsj3_sx_v123', '["jsj3_sx","qimo3","p122","choice_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1035, '数学', '三年级', 'apply', 2, '{"stem": "应用(1)：水星绕太阳一圈要88天，火星绕太阳一圈要687天，地球绕太阳一圈的天数比水星和火星的总和少410天。地球绕太阳转一圈要多少天？"}', '365（天）', '88+687-410=365', 'jsj3_sx_v123', '["jsj3_sx","qimo3","p122","apply_01"]', 1, NULL);
