INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 3, '{"stem": "应用(4)：某国货品牌开直播10分钟的销售情况：毛衣每件128元卖了6件，风衣每件238元卖了4件。风衣比毛衣多卖了多少元？"}', '184（元）', '238×4=952, 128×6=768, 952-768=184', 'jsj3_sx_v123', '["jsj3_sx","qimo3","p123","apply_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'apply', 3, '{"stem": "应用(5)：大显示屏是由两块如图所示的小显示屏（长12分米、宽8分米）拼接而成的，这个大显示屏的周长最短是多少分米？"}', '56（分米）', '长边拼接→大屏宽12, 长8×2=16, (12+16)×2=56', 'jsj3_sx_v123', '["jsj3_sx","qimo3","p123","apply_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'apply', 3, '{"stem": "应用(6)：学校在校外劳动实践基地的土地上利用墙作为一边，划出一块长方形菜地，将这块菜地围上篱笆，篱笆长40米，菜地宽12米（靠墙的一边是宽），这块地的长是多少米？"}', '14（米）', '靠墙一边是宽12m→篱笆=2长+1宽=40, 2长=40-12=28, 长=14', 'jsj3_sx_v123', '["jsj3_sx","qimo3","p123","apply_06"]', 1, NULL);